INSERT INTO repo_subtopics (subtopic_id, name, subtopic_no, description, subtopic_sd_id, review_status, status, version) VALUES ('SUB_COURSE_047_M1_S4', 'IGBTs', '4', 'IGBTs: Insulated-gate bipolar transistors combining MOS-gate control with bipolar conduction for medium- and high-power switching. In Power Semiconductor Devices, the focus is on the analysis, design, implementation, interpretation, or evaluation of IGBTs within Power Electronics, particularly where the Power Semiconductor Devices module establishes its technical context.', 'SSD_COURSE_047_M1_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_047_M1_S5', 'SiC and GaN devices', '5', 'SiC and GaN devices: Wide-bandgap semiconductor devices offering high switching speed, temperature capability, and power density. In Power Semiconductor Devices, the focus is on the analysis, design, implementation, interpretation, or evaluation of SiC and GaN devices within Power Electronics, particularly where the Power Semiconductor Devices module establishes its technical context.', 'SSD_COURSE_047_M1_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_047_M2_S1', 'uncontrolled rectifiers', '1', 'uncontrolled rectifiers: Methods used to regulate uncontrolled rectifiers by measuring relevant conditions and applying defined control actions or constraints. In Controlled Rectifiers, the focus is on the analysis, design, implementation, interpretation, or evaluation of uncontrolled rectifiers within Power Electronics, particularly where the Controlled Rectifiers module establishes its technical context.', 'SSD_COURSE_047_M2_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_047_M2_S2', 'phase-controlled converters', '2', 'phase-controlled converters: Methods used to regulate phase-controlled converters by measuring relevant conditions and applying defined control actions or constraints. In Controlled Rectifiers, the focus is on the analysis, design, implementation, interpretation, or evaluation of phase-controlled converters within Power Electronics, particularly where the Controlled Rectifiers module establishes its technical context.', 'SSD_COURSE_047_M2_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_047_M2_S3', 'commutation', '3', 'commutation: Transfer of current between semiconductor devices or phases in a power-electronic converter. In Controlled Rectifiers, the focus is on the analysis, design, implementation, interpretation, or evaluation of commutation within Power Electronics, particularly where the Controlled Rectifiers module establishes its technical context.', 'SSD_COURSE_047_M2_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_047_M2_S4', 'harmonics', '4', 'harmonics: Sinusoidal components whose frequencies are integer multiples of a fundamental frequency, arising from nonlinear or switching behaviour and affecting waveform quality and equipment performance. In Controlled Rectifiers, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_047_M2_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_047_M3_S1', 'buck', '1', 'buck refers to a DC-DC converter topology that produces a lower average output voltage than its input under ideal continuous operation. In DC-DC Converters, the focus is on the analysis, design, implementation, interpretation, or evaluation of buck within Power Electronics, particularly where the DC-DC Converters module establishes its technical context.', 'SSD_COURSE_047_M3_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_047_M3_S2', 'boost', '2', 'boost refers to a DC-DC converter topology that produces a higher average output voltage than its input under ideal operation. In DC-DC Converters, the focus is on the analysis, design, implementation, interpretation, or evaluation of boost within Power Electronics, particularly where the DC-DC Converters module establishes its technical context.', 'SSD_COURSE_047_M3_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_047_M3_S3', 'buck-boost', '3', 'buck-boost refers to a family of DC-DC converter topologies capable of producing an output voltage magnitude below or above the input. In DC-DC Converters, the focus is on the analysis, design, implementation, interpretation, or evaluation of buck-boost within Power Electronics, particularly where the DC-DC Converters module establishes its technical context.', 'SSD_COURSE_047_M3_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_047_M3_S4', 'isolated converters', '4', 'isolated converters: Power converters using magnetic isolation, typically through a transformer, between input and output. In DC-DC Converters, the focus is on the analysis, design, implementation, interpretation, or evaluation of isolated converters within Power Electronics, particularly where the DC-DC Converters module establishes its technical context.', 'SSD_COURSE_047_M3_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_047_M3_S5', 'continuous/discontinuous conduction', '5', 'continuous/discontinuous conduction: Operating modes distinguished by whether converter inductor current remains above zero throughout a switching period. In DC-DC Converters, the focus is on the analysis, design, implementation, interpretation, or evaluation of continuous/discontinuous conduction within Power Electronics, particularly where the DC-DC Converters module establishes its technical context.', 'SSD_COURSE_047_M3_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_047_M4_S1', 'voltage-source inverters', '1', 'voltage-source inverters: Inverters supplied from a stiff DC voltage source and controlled to produce AC output. In Inverters, the focus is on the analysis, design, implementation, interpretation, or evaluation of voltage-source inverters within Power Electronics, particularly where the Inverters module establishes its technical context.', 'SSD_COURSE_047_M4_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_047_M4_S2', 'current-source inverters', '2', 'current-source inverters: Inverters supplied from a controlled DC current source and used to produce AC output. In Inverters, the focus is on the analysis, design, implementation, interpretation, or evaluation of current-source inverters within Power Electronics, particularly where the Inverters module establishes its technical context.', 'SSD_COURSE_047_M4_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_047_M4_S3', 'single-phase', '3', 'single-phase: Power converters designed for single-phase AC systems. In Inverters, the focus is on the analysis, design, implementation, interpretation, or evaluation of single-phase within Power Electronics, particularly where the Inverters module establishes its technical context.', 'SSD_COURSE_047_M4_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_047_M4_S4', 'three-phase', '4', 'three-phase: Power converters designed for three-phase AC systems and their associated switching patterns. In Inverters, the focus is on the analysis, design, implementation, interpretation, or evaluation of three-phase within Power Electronics, particularly where the Inverters module establishes its technical context.', 'SSD_COURSE_047_M4_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_047_M5_S1', 'carrier-based PWM', '1', 'carrier-based PWM: Pulse-width modulation produced by comparing a reference waveform with a high-frequency carrier. In PWM and Switching Control, the focus is on the analysis, design, implementation, interpretation, or evaluation of carrier-based PWM within Power Electronics, particularly where the PWM and Switching Control module establishes its technical context.', 'SSD_COURSE_047_M5_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_047_M5_S2', 'space-vector PWM', '2', 'space-vector PWM refers to a three-phase PWM method that represents inverter switching states as vectors in a two-dimensional plane. In PWM and Switching Control, the focus is on the analysis, design, implementation, interpretation, or evaluation of space-vector PWM within Power Electronics, particularly where the PWM and Switching Control module establishes its technical context.', 'SSD_COURSE_047_M5_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_047_M5_S3', 'switching losses', '3', 'switching losses: Power dissipated during semiconductor turn-on and turn-off transitions. In PWM and Switching Control, the focus is on the analysis, design, implementation, interpretation, or evaluation of switching losses within Power Electronics, particularly where the PWM and Switching Control module establishes its technical context.', 'SSD_COURSE_047_M5_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_047_M5_S4', 'gate drives', '4', 'gate drives: Circuits that provide the required control signals and electrical conditions for switching power devices. In PWM and Switching Control, the focus is on the analysis, design, implementation, interpretation, or evaluation of gate drives within Power Electronics, particularly where the PWM and Switching Control module establishes its technical context.', 'SSD_COURSE_047_M5_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_047_M6_S1', 'harmonics', '1', 'harmonics: Sinusoidal components whose frequencies are integer multiples of a fundamental frequency, arising from nonlinear or switching behaviour and affecting waveform quality and equipment performance. In Power Quality and Thermal Management, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_047_M6_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_047_M6_S2', 'power factor', '2', 'power factor refers to the ratio of real power to apparent power in an AC electrical system, indicating how effectively current contributes to useful power transfer. In Power Quality and Thermal Management, the focus is on the analysis, design, implementation, interpretation, or evaluation of power factor within Power Electronics, particularly where the Power Quality and Thermal Management module establishes its technical context.', 'SSD_COURSE_047_M6_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_047_M6_S3', 'Electromagnetic Interference (EMI)', '3', 'EMI: Electromagnetic interference produced by switching and power-electronic circuits that can disturb other equipment. In Power Quality and Thermal Management, the focus is on the analysis, design, implementation, interpretation, or evaluation of EMI within Power Electronics, particularly where the Power Quality and Thermal Management module establishes its technical context.', 'SSD_COURSE_047_M6_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_047_M6_S4', 'thermal design', '4', 'thermal design refers to the structured process of defining requirements, constraints, alternatives, and implementation decisions for thermal design. In Power Quality and Thermal Management, the focus is on the analysis, design, implementation, interpretation, or evaluation of thermal design within Power Electronics, particularly where the Power Quality and Thermal Management module establishes its technical context.', 'SSD_COURSE_047_M6_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_047_M6_S5', 'heat sinks', '5', 'heat sinks: Thermal components that conduct and dissipate heat from power semiconductor devices or other heat-generating components to a surrounding medium. In Power Quality and Thermal Management, the focus is on the analysis, design, implementation, interpretation, or evaluation of heat sinks within Power Electronics, particularly where the Power Quality and Thermal Management module establishes its technical context.', 'SSD_COURSE_047_M6_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_047_M7_S1', 'motor drives', '1', 'motor drives: Power-electronic systems that control electric-motor voltage, current, speed, or torque. In Applications of Power Electronics, the focus is on the analysis, design, implementation, interpretation, or evaluation of motor drives within Power Electronics, particularly where the Applications of Power Electronics module establishes its technical context.', 'SSD_COURSE_047_M7_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_047_M7_S2', 'renewable interfaces', '2', 'renewable interfaces: Power-electronic interfaces connecting renewable generators such as PV or wind systems to loads or electrical grids. In Applications of Power Electronics, the focus is on the analysis, design, implementation, interpretation, or evaluation of renewable interfaces within Power Electronics, particularly where the Applications of Power Electronics module establishes its technical context.', 'SSD_COURSE_047_M7_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_047_M7_S3', 'Uninterruptible Power Supply (UPS)', '3', 'UPS: Uninterruptible power supply systems that provide conditioned electrical power and temporary ride-through or backup power to loads when the normal supply is disturbed or unavailable. In Applications of Power Electronics, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_047_M7_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_047_M7_S4', 'High-Voltage Direct Current (HVDC)', '4', 'HVDC: High-Voltage Direct Current transmission using power-electronic converters to transfer electrical power over long distances or between asynchronous systems. In Applications of Power Electronics, the focus is on the analysis, design, implementation, interpretation, or evaluation of HVDC within Power Electronics, particularly where the Applications of Power Electronics module establishes its technical context.', 'SSD_COURSE_047_M7_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_047_M7_S5', 'EV charging', '5', 'EV charging: Power-conversion systems that safely transfer electrical energy from a supply to an electric vehicle battery. In Applications of Power Electronics, the focus is on the analysis, design, implementation, interpretation, or evaluation of EV charging within Power Electronics, particularly where the Applications of Power Electronics module establishes its technical context.', 'SSD_COURSE_047_M7_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_048_M1_S1', 'accuracy', '1', 'accuracy: Closeness of a measurement result to a reference or accepted value. In Measurement Fundamentals and Errors, the focus is on the analysis, design, implementation, interpretation, or evaluation of accuracy within Electrical Measurements and Instrumentation, particularly where the Measurement Fundamentals and Errors module establishes its technical context.', 'SSD_COURSE_048_M1_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_048_M1_S2', 'precision', '2', 'precision: Closeness of agreement among repeated measurement results under specified conditions. In Measurement Fundamentals and Errors, the focus is on the analysis, design, implementation, interpretation, or evaluation of precision within Electrical Measurements and Instrumentation, particularly where the Measurement Fundamentals and Errors module establishes its technical context.', 'SSD_COURSE_048_M1_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_048_M1_S3', 'Measurement sensitivity', '3', 'Measurement sensitivity: Change in measurement-system output per unit change in the measurand or input quantity, considered together with resolution, noise, range, and uncertainty when evaluating an instrument. In Measurement Fundamentals and Errors, the focus is on curricular scope: Electrical Measurements and Instrumentation; The concept is represented at the level of the stated mechanism, properties, constraints, and application criteria.', 'SSD_COURSE_048_M1_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_048_M1_S4', 'resolution', '4', 'resolution: Smallest change in the measured quantity that an instrument can distinguish under stated conditions. In Measurement Fundamentals and Errors, the focus is on the analysis, design, implementation, interpretation, or evaluation of resolution within Electrical Measurements and Instrumentation, particularly where the Measurement Fundamentals and Errors module establishes its technical context.', 'SSD_COURSE_048_M1_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_048_M1_S5', 'systematic and random error', '5', 'systematic and random error: Measurement effects that cause consistent bias or unpredictable variation, respectively. In Measurement Fundamentals and Errors, the focus is on the analysis, design, implementation, interpretation, or evaluation of systematic and random error within Electrical Measurements and Instrumentation, particularly where the Measurement Fundamentals and Errors module establishes its technical context.', 'SSD_COURSE_048_M1_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_048_M2_S1', 'Permanent-Magnet Moving-Coil (PMMC)', '1', 'PMMC: Permanent-Magnet Moving-Coil instruments that measure DC quantities using torque on a current-carrying coil in a permanent magnetic field. In Electrical Measuring Instruments, the focus is on the analysis, design, implementation, interpretation, or evaluation of PMMC within Electrical Measurements and Instrumentation, particularly where the Electrical Measuring Instruments module establishes its technical context.', 'SSD_COURSE_048_M2_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_048_M2_S2', 'moving-iron', '2', 'moving-iron: Instruments that use magnetic forces on iron elements to indicate electrical current or voltage. In Electrical Measuring Instruments, the focus is on the analysis, design, implementation, interpretation, or evaluation of moving-iron within Electrical Measurements and Instrumentation, particularly where the Electrical Measuring Instruments module establishes its technical context.', 'SSD_COURSE_048_M2_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_048_M2_S3', 'dynamometer', '3', 'dynamometer: Electrodynamic instruments using interaction between fixed and moving coils to measure electrical quantities. In Electrical Measuring Instruments, the focus is on the analysis, design, implementation, interpretation, or evaluation of dynamometer within Electrical Measurements and Instrumentation, particularly where the Electrical Measuring Instruments module establishes its technical context.', 'SSD_COURSE_048_M2_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_048_M2_S4', 'digital instruments', '4', 'digital instruments: Measurement instruments that convert sensed quantities into digital signals and present or process the resulting numerical measurements. In Electrical Measuring Instruments, the focus is on the analysis, design, implementation, interpretation, or evaluation of digital instruments within Electrical Measurements and Instrumentation, particularly where the Electrical Measuring Instruments module establishes its technical context.', 'SSD_COURSE_048_M2_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_048_M2_S5', 'instrument transformers', '5', 'instrument transformers: Transformers used to scale high currents or voltages to standardized levels suitable for measurement, protection, and instrumentation. In Electrical Measuring Instruments, the focus is on the analysis, design, implementation, interpretation, or evaluation of instrument transformers within Electrical Measurements and Instrumentation, particularly where the Electrical Measuring Instruments module establishes its technical context.', 'SSD_COURSE_048_M2_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_048_M3_S1', 'resistive', '1', 'resistive: Transducers whose output changes with a measurand through a change in electrical resistance. In Sensors and Transducers, the focus is on the analysis, design, implementation, interpretation, or evaluation of resistive within Electrical Measurements and Instrumentation, particularly where the Sensors and Transducers module establishes its technical context.', 'SSD_COURSE_048_M3_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_048_M3_S2', 'inductive', '2', 'inductive: Transducers that sense a measurand through a change in inductance or magnetic coupling. In Sensors and Transducers, the focus is on the analysis, design, implementation, interpretation, or evaluation of inductive within Electrical Measurements and Instrumentation, particularly where the Sensors and Transducers module establishes its technical context.', 'SSD_COURSE_048_M3_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_048_M3_S3', 'capacitive', '3', 'capacitive: Transducers that sense a measurand through a change in capacitance. In Sensors and Transducers, the focus is on the analysis, design, implementation, interpretation, or evaluation of capacitive within Electrical Measurements and Instrumentation, particularly where the Sensors and Transducers module establishes its technical context.', 'SSD_COURSE_048_M3_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_048_M3_S4', 'thermoelectric', '4', 'thermoelectric: Transducers that generate an electrical output related to temperature through thermoelectric effects. In Sensors and Transducers, the focus is on the analysis, design, implementation, interpretation, or evaluation of thermoelectric within Electrical Measurements and Instrumentation, particularly where the Sensors and Transducers module establishes its technical context.', 'SSD_COURSE_048_M3_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_048_M3_S5', 'magnetic', '5', 'magnetic: Transducers that measure quantities using changes in magnetic field, flux, or magnetic properties. In Sensors and Transducers, the focus is on the analysis, design, implementation, interpretation, or evaluation of magnetic within Electrical Measurements and Instrumentation, particularly where the Sensors and Transducers module establishes its technical context.', 'SSD_COURSE_048_M3_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_048_M3_S6', 'optical transducers', '6', 'optical transducers: Devices that convert a physical quantity into a measurable optical change or convert optical signals into electrical signals. In Sensors and Transducers, the focus is on the analysis, design, implementation, interpretation, or evaluation of optical transducers within Electrical Measurements and Instrumentation, particularly where the Sensors and Transducers module establishes its technical context.', 'SSD_COURSE_048_M3_S6', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_048_M4_S1', 'amplification', '1', 'amplification: Increase in the magnitude of a signal or physical quantity using an active or passive mechanism, subject to gain, bandwidth, distortion, noise, and stability constraints. In Signal Conditioning and Data Acquisition, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_048_M4_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_048_M4_S2', 'filtering', '2', 'filtering: Selective attenuation or passage of signal components according to frequency, time, spatial characteristics, or other defined criteria. In Signal Conditioning and Data Acquisition, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_048_M4_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_048_M4_S3', 'Measurement isolation', '3', 'Measurement isolation: Electrical or functional isolation used to prevent unwanted conductive interaction between signal paths, measurement circuits, or system elements while preserving the required transfer of information or energy. In Signal Conditioning and Data Acquisition, the focus is on curricular scope: Mechatronics; Electrical Measurements and Instrumentation; The concept is represented at the level of the stated mechanism, properties, constraints, and application criteria.', 'SSD_COURSE_048_M4_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_048_M4_S4', 'Analog-to-Digital / Digital-to-Analog Conversion (ADC/DAC)', '4', 'ADC/DAC: Analog-to-digital and digital-to-analog conversion processes used to interface continuous-valued signals with digital systems. In Signal Conditioning and Data Acquisition, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_048_M4_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_048_M4_S5', 'Signal sampling', '5', 'Signal sampling: Conversion of a continuous-time signal into discrete samples at specified sampling instants; sampling rate and reconstruction requirements determine aliasing and information loss. In Signal Conditioning and Data Acquisition, the focus is on curricular scope: Mechatronics; Electrical Measurements and Instrumentation; The concept is represented at the level of the stated mechanism, properties, constraints, and application criteria.', 'SSD_COURSE_048_M4_S5', 'Semantically_Audited', 'Active', '4.0') ON CONFLICT DO NOTHING;